  pub struct KeyChord { pub modifiers: ModSet, pub key: PhysicalKey }
  // ModSet + PhysicalKey come from phux-protocol::input (re-exported via phux-core or used directly).

  pub struct KeybindSequence(pub Vec<KeyChord>);
    // 'C-b c' parses to [Chord{Ctrl, 'b'}, Chord{∅, 'c'}].

  pub struct Resolver {
      // ART/trie keyed on chord sequences. Lookup state machine:
      // partial → 'awaiting next chord'; full match → ResolvedAction.
  }

  pub struct ResolvedAction { pub action: String, pub args: Vec<String> }

  impl Resolver {
      pub fn new(binds: &[KeybindCfg]) -> Result<Self, KeybindError>;
      pub fn feed(&mut self, chord: KeyChord) -> Option<ResolvedAction>;
      pub fn reset(&mut self);
  }

Parser for chord strings: 'C-' Ctrl, 'M-' Meta/Alt, 'S-' Shift, 'A-' Alt.
Multi-chord separated by spaces. Tokens: alphanumerics, 'Tab', 'Enter',
'Esc', 'F1'..'F24', 'Up'/'Down'/'Left'/'Right', etc.

Snapshot test (crates/phux-config/tests/keybind_snapshots.rs):
  - 'C-b c' parses to expected KeybindSequence (insta snapshot)
  - 'M-S-Tab' parses with both modifiers
  - feed() sequences across multiple chords resolve correctly
  - ambiguous prefixes ('C-b' alone, 'C-b c', 'C-b d') don't confuse the
    trie (snapshot the lookup table)

Note: this MUST line up with libghostty's KeyEvent encoding from
phux-6yl. Use the same ModSet bit ordering — re-export from phux-protocol
rather than duplicating (ADR-0008).

